content.css:
/* Premium KPI v2 — Dark executive theme */
.kpi-card {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 16px 20px;
  background: #151d2e;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
  overflow: hidden;
}
/* Icon circle */
.kpi-icon-circle {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(56, 152, 255, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
}
.kpi-icon-text {
  color: #3898ff;
  font-weight: 600;
  font-size: 18px;
  line-height: 1;
}
/* Content area */
.kpi-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.kpi-label {
  font-size: 11px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.55);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-value {
  font-size: 32px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.5px;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 0 0 #111;
}
/* Delta area */
.kpi-delta {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}
.kpi-delta-arrow {
  font-size: 10px;
  display: inline;
}
.kpi-delta-arrow.positive {
  color: #34d399;
}
.kpi-delta-arrow.negative {
  color: #f87171;
}
.kpi-delta-value {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}
.kpi-delta-value.positive {
  color: #34d399;
}
.kpi-delta-value.negative {
  color: #f87171;
}
.kpi-delta-context {
  font-size: 9px;
  color: rgba(255, 255, 255, 0.35);
  white-space: nowrap;
}
